// One-off: seed epic-scoped lane-state markers for lanes merged before the
// marker system existed (datum#281). Run from the-record-suite repo root.
import { readFileSync, writeFileSync, mkdirSync } from 'node:fs'
import { execSync } from 'node:child_process'
import { laneSpecHash, epicSlug } from '/Volumes/Extra/repos/gitrdunhq/datum/.temp/ts-test/utils.mjs'

const EPIC_BRANCH = 'datum/epic-287'
const MERGED = [
  { task_id: 'task-001', ref: '1049fc77', run_id: '20260706-105404-b0' },
  { task_id: 'task-005', ref: '1049fc77', run_id: '20260706-105404-b0' },
  { task_id: 'task-006', ref: '6f60bd70', run_id: '20260706-121711-b1' },
  { task_id: 'task-008', ref: 'c0ea85e0', run_id: '20260706-121711-b1' },
]

const lanePlan = JSON.parse(readFileSync('docs/epics/datum/epic-287/lane-plan.json', 'utf8'))
const dir = `.datum/epics/${epicSlug(EPIC_BRANCH)}/lane-state`
mkdirSync(dir, { recursive: true })

for (const m of MERGED) {
  const mergeCommit = execSync(`git rev-parse ${m.ref}`).toString().trim()
  const completedAt = execSync(`git show -s --format=%cI ${m.ref}`).toString().trim()
  const marker = {
    schema_version: '1.0',
    task_id: m.task_id,
    status: 'completed',
    epic_branch: EPIC_BRANCH,
    merge_commit: mergeCommit,
    spec_hash: laneSpecHash(lanePlan.lanes[m.task_id]),
    run_id: m.run_id,
    completed_at: completedAt,
  }
  writeFileSync(`${dir}/${m.task_id}.json`, JSON.stringify(marker, null, 2) + '\n')
  console.log(`${m.task_id} → ${marker.spec_hash} @ ${mergeCommit.slice(0, 8)}`)
}
